sp_widget.css:
.ehr-page {
  max-width: 1100px;
  margin: 30px auto;
  padding: 0 20px 40px;
  color: #14213d;
}


/* HEADER */

.ehr-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 25px;
}

.ehr-header h2 {
  margin: 0 0 6px;
  font-size: 30px;
  font-weight: 700;
  color: #14213d;
}

.ehr-header p {
  margin: 0;
  color: #718096;
  font-size: 14px;
}

.ehr-back {
  color: #0066cc;
  text-decoration: none;
  font-size: 14px;
  margin-top: 8px;
}

.ehr-back:hover {
  text-decoration: underline;
}


/* SUMMARY */

.ehr-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-bottom: 20px;
}

.ehr-summary-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  padding: 20px;
  box-shadow: 0 3px 12px rgba(0,0,0,0.05);
}

.ehr-summary-card > span {
  display: block;
  color: #718096;
  font-size: 12px;
  margin-bottom: 10px;
}

.ehr-summary-card strong {
  font-size: 15px;
  color: #14213d;
}


/* STATUS */

.status-pill {
  display: inline-block;
  padding: 6px 12px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
}

.status-open {
  background: #edf2f7;
  color: #4a5568;
}

.status-progress {
  background: #e8f1ff;
  color: #1d5fbf;
}

.status-awaiting {
  background: #fff4d6;
  color: #a35d00;
}

.status-resolved {
  background: #dcfce7;
  color: #15803d;
}

.status-closed {
  background: #edf0f4;
  color: #596273;
}


/* GENERAL CARD */

.ehr-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  padding: 22px;
  margin-bottom: 20px;
  box-shadow: 0 3px 14px rgba(0,0,0,0.05);
}

.ehr-card-header {
  margin-bottom: 18px;
}

.ehr-card-header h3 {
  margin: 0 0 5px;
  font-size: 18px;
  font-weight: 700;
  color: #14213d;
}

.ehr-card-header p {
  margin: 0;
  color: #718096;
  font-size: 13px;
}


/* CASE INFORMATION */

.ehr-info-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 22px;
}

.ehr-field label {
  display: block;
  color: #718096;
  font-size: 12px;
  margin-bottom: 6px;
}

.ehr-field div {
  font-weight: 600;
  color: #14213d;
}

.muted-text {
  color: #94a3b8 !important;
  font-weight: 400 !important;
}


/* EMPLOYEE REQUEST */

.ehr-request-box {
  padding: 20px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 10px;
  line-height: 1.7;
  color: #334155;
  white-space: pre-line;
}


/* PROCESSING */

.ehr-processing {
  display: flex;
  align-items: center;
  gap: 18px;
}

.processing-icon {
  width: 52px;
  height: 52px;
  min-width: 52px;
  border-radius: 50%;
  background: #e8f1ff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 24px;
}

.ehr-processing h3 {
  margin: 0 0 6px;
  font-size: 17px;
  color: #14213d;
}

.ehr-processing p {
  margin: 0;
  color: #718096;
  line-height: 1.6;
}


/* PROPOSED RESOLUTION */

.confirmation-card {
  border-left: 4px solid #0891b2;
}

.resolution-badge {
  display: inline-block;
  background: #dcfce7;
  color: #15803d;
  border-radius: 20px;
  padding: 5px 11px;
  font-size: 11px;
  font-weight: 700;
  margin-bottom: 10px;
}

.proposed-resolution {
  background: #ecfdf5;
  border: 1px solid #bbf7d0;
  border-radius: 10px;
  padding: 20px;
  margin-top: 18px;
}

.resolution-title {
  font-size: 12px;
  font-weight: 700;
  color: #15803d;
  margin-bottom: 10px;
}

.resolution-text {
  color: #334155;
  line-height: 1.7;
  white-space: pre-line;
}


/* RESOLVED */

.resolved-card {
  text-align: center;
  padding: 30px;
}

.resolved-icon {
  width: 58px;
  height: 58px;
  margin: 0 auto 15px;
  border-radius: 50%;
  background: #dcfce7;
  color: #15803d;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 30px;
  font-weight: bold;
}

.resolved-card h3 {
  color: #14213d;
}

.resolved-card > p {
  color: #718096;
}

.final-resolution {
  max-width: 750px;
  margin: 20px auto 0;
  text-align: left;
  background: #ecfdf5;
  border: 1px solid #bbf7d0;
  border-radius: 10px;
  padding: 18px;
}

.final-resolution strong {
  color: #15803d;
}

.final-resolution p {
  margin: 8px 0 0;
  line-height: 1.7;
  color: #334155;
  white-space: pre-line;
}


/* MESSAGES */

.ehr-message {
  border-radius: 8px;
  padding: 13px 16px;
  margin: 15px 0;
  font-size: 13px;
}

.ehr-message.error {
  background: #fee2e2;
  border: 1px solid #fecaca;
  color: #b91c1c;
}

.ehr-message.info {
  background: #eff6ff;
  border: 1px solid #bfdbfe;
  color: #1e40af;
}


/* RESPONSIVE */

@media (max-width: 850px) {

  .ehr-summary-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .ehr-info-grid {
    grid-template-columns: 1fr;
  }

}

@media (max-width: 550px) {

  .ehr-page {
    padding: 0 12px 30px;
  }

  .ehr-header {
    flex-direction: column;
    gap: 12px;
  }

  .ehr-summary-grid {
    grid-template-columns: 1fr;
  }

}

sp_widget.script:
(function() {

    // ==========================================
    // INITIAL DATA
    // ==========================================

    data.caseFound = false;
    data.hasAccess = false;
    data.error = false;
    data.message = "";
    data.case = {};

    var userId = gs.getUserID();

    var hodDepartmentId = "";


    // ==========================================
    // GET LOGGED-IN HOD DEPARTMENT
    // ==========================================

    var userGR =
        new GlideRecord('sys_user');

    if (userGR.get(userId)) {

        hodDepartmentId =
            userGR.getValue(
                'department'
            ) || "";
    }


    if (!hodDepartmentId) {

        data.error = true;

        data.message =
            "No department is associated with the logged-in HOD.";

        return;
    }


    // ==========================================
    // GET CASE SYS_ID
    // ==========================================

    var caseSysId = "";

    if (input && input.sys_id) {

        caseSysId =
            input.sys_id;

    } else {

        caseSysId =
            $sp.getParameter(
                'sys_id'
            );
    }


    if (!caseSysId) {

        data.error = true;

        data.message =
            "No HR case was selected.";

        return;
    }


    // ==========================================
    // LOAD HR CASE
    // ==========================================

    var caseGR =
        new GlideRecord(
            'x_snc_unified_hr_0_hr_case'
        );


    if (!caseGR.get(caseSysId)) {

        data.error = true;

        data.message =
            "HR Case not found.";

        return;
    }


    data.caseFound = true;


    // ==========================================
    // GET REQUESTER
    // ==========================================

    var requestedById =
        caseGR.getValue(
            'request_by'
        );


    if (!requestedById) {

        data.error = true;

        data.message =
            "This HR case does not have a requester.";

        return;
    }


    // ==========================================
    // DO NOT ALLOW HOD'S OWN CASE
    // THROUGH DEPARTMENT VIEW
    // ==========================================

    if (requestedById == userId) {

        data.error = true;

        data.message =
            "Your own HR cases should be viewed from My HR Requests.";

        return;
    }


    // ==========================================
    // LOAD REQUESTER USER
    // ==========================================

    var requesterGR =
        new GlideRecord(
            'sys_user'
        );


    if (!requesterGR.get(
        requestedById
    )) {

        data.error = true;

        data.message =
            "Requester information could not be found.";

        return;
    }


    // ==========================================
    // DEPARTMENT ACCESS CHECK
    // ==========================================

    var requesterDepartmentId =
        requesterGR.getValue(
            'department'
        ) || "";


    if (
        requesterDepartmentId !=
        hodDepartmentId
    ) {

        data.error = true;

        data.message =
            "You are not authorized to view this HR case.";

        return;
    }


    data.hasAccess = true;


    // ==========================================
    // CREATED DATE
    // ==========================================

    var createdOn =
        caseGR.getDisplayValue(
            'created_on'
        );


    if (!createdOn) {

        createdOn =
            caseGR.getDisplayValue(
                'sys_created_on'
            );
    }


    // ==========================================
    // STATUS
    // ==========================================

    var statusValue =
        caseGR.getValue(
            'status'
        ) || "";


    var statusLabel =
        caseGR.getDisplayValue(
            'status'
        ) || "";


    if (
        statusValue ==
        'awaiting_employee_confirmation'
    ) {

        statusLabel =
            'Awaiting Employee Confirmation';
    }


    // ==========================================
    // PREPARE CASE DATA
    // ==========================================

    data.case = {

        sys_id:
            caseGR.getUniqueValue(),

        number:
            caseGR.getDisplayValue(
                'number'
            ),

        requested_by:
            caseGR.getDisplayValue(
                'request_by'
            ),

        department:
            requesterGR.getDisplayValue(
                'department'
            ),

        category:
            caseGR.getDisplayValue(
                'category'
            ),

        priority:
            caseGR.getDisplayValue(
                'priority'
            ),

        assignment_group:
            caseGR.getDisplayValue(
                'assignment_group'
            ),

        assigned_to:
            caseGR.getDisplayValue(
                'assigned_to'
            ),

        status:
            statusLabel,

        status_value:
            statusValue,

        description:
            caseGR.getDisplayValue(
                'description'
            ),

        resolution_notes:
            caseGR.getDisplayValue(
                'resolution_notes'
            ),

        rejection_feedback:
            caseGR.getDisplayValue(
                'rejection_feedback'
            ),

        resolution_proposed_on:
            caseGR.getDisplayValue(
                'resolution_proposed_on'
            ),

        created_on:
            createdOn

    };

})();
